+            "_source": {
+               "foo": "foo"
+            },
+            "executed_pipelines": []
+         }
+      },
+      {
+         "doc": {
+            "_id": "456",
+            "_index": "my-index",
+            "_version": -3,
+            "_source": {
+               "bar": "rab"
+            },
+            "executed_pipelines": []
+         }
+      }
+   ]
+}
